package sn.ucad.nexora.espace.presentation.mapper;
import java.util.List; import org.springframework.stereotype.Component; import sn.ucad.nexora.espace.application.dto.response.EspaceResponse; import sn.ucad.nexora.espace.domain.entity.EspaceProfessionnel; import sn.ucad.nexora.espace.infrastructure.persistence.entity.AdresseJpaEntity;
@Component public class EspacePresentationMapper{
 public EspaceResponse toResponse(EspaceProfessionnel e){EspaceResponse r=new EspaceResponse();r.setId(e.getId());r.setUtilisateurId(e.getUtilisateurId());r.setTypeEspaceId(e.getTypeEspaceId());r.setNom(e.getNom());r.setSlogan(e.getSlogan());r.setDescription(e.getDescription());r.setTelephone(e.getTelephone());r.setTelephoneSecondaire(e.getTelephoneSecondaire());r.setEmail(e.getEmail());r.setSiteWeb(e.getSiteWeb());r.setLogo(e.getLogo());r.setCouverture(e.getCouverture());r.setOuvert(e.isOuvert());r.setStatut(e.getStatut());r.setCertifie(e.isCertifie());r.setVerifie(e.isVerifie());r.setNoteMoyenne(e.getNoteMoyenne());r.setNombreAvis(e.getNombreAvis());r.setNombreVues(e.getNombreVues());r.setNombreFavoris(e.getNombreFavoris());r.setNombreJaime(e.getNombreJaime());r.setDateCreation(e.getDateCreation());r.setRegistreCommerce(e.getRegistreCommerce());r.setNumeroNinea(e.getNumeroNinea());r.setNumeroRccm(e.getNumeroRccm());return r;}
 public EspaceResponse toResponse(EspaceProfessionnel e,AdresseJpaEntity a){EspaceResponse r=toResponse(e);if(a!=null){r.setPays(a.getPays());r.setRegion(a.getRegion());r.setDepartement(a.getDepartement());r.setCommune(a.getCommune());r.setQuartier(a.getQuartier());r.setAdresseComplete(a.getAdresseComplete());r.setLatitude(a.getLatitude());r.setLongitude(a.getLongitude());}return r;}
 public EspaceResponse toResponse(EspaceProfessionnel e,AdresseJpaEntity a,List<String> photos){EspaceResponse r=toResponse(e,a);r.setPhotos(photos);return r;}
}
